 "content": "from collections import Counter, deque


def transform(grid):
    """Fill each hollow rectangular outline based on its outer side parity."""
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    output = [row[:] for row in grid]
    visited = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in visited:
                continue
            component = set()
            queue = deque([(r, c)])
            visited.add((r, c))
            while queue:
                rr, cc = queue.popleft()
                component.add((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in visited and grid[nr][nc] == color:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

            r1 = min(rr for rr, _ in component)
            r2 = max(rr for rr, _ in component)
            c1 = min(cc for _, cc in component)
            c2 = max(cc for _, cc in component)
            if r2 - r1 < 2 or c2 - c1 < 2:
                continue
            expected_border = {
                (rr, cc)
                for rr in range(r1, r2 + 1)
                for cc in range(c1, c2 + 1)
                if rr in (r1, r2) or cc in (c1, c2)
            }
            if component != expected_border:
                continue
            if not all(grid[rr][cc] == background for rr in range(r1 + 1, r2) for cc in range(c1 + 1, c2)):
                continue

            side = r2 - r1 + 1
            fill = 7 if side % 2 == 1 else 2
            for rr in range(r1 + 1, r2):
                for cc in range(c1 + 1, c2):
                    output[rr][cc] = fill
    return output
